-- Generated by Claude Code — Erinnerungen und Wirkungsstatistik für Promotionen.

-- Zeitstempel, damit der tägliche Cron jede Erinnerung nur einmal verschickt.
alter table event_promotions
  add column if not exists payment_reminder_sent_at timestamptz,
  add column if not exists review_reminder_sent_at timestamptz,
  add column if not exists summary_sent_at timestamptz;
alter table entity_claims
  add column if not exists review_reminder_sent_at timestamptz;

create index if not exists event_views_event_time_idx on event_views (event_id, viewed_at);
create index if not exists ticket_clicks_event_time_idx on ticket_clicks (event_id, clicked_at);
create index if not exists home_feed_impressions_event_time_idx on home_feed_impressions (event_id, shown_at);

-- Wirkung einer Promotion: Aufrufe, Ticket-Klicks und Feed-Einblendungen
-- während der Laufzeit, verglichen mit dem Tagesschnitt der 14 Tage davor.
-- Liefert nur Summen, keine personenbezogenen Daten.
create or replace function promotion_performance(p_promotion_id uuid)
returns table (
  days_running numeric,
  views_during bigint,
  views_per_day_before numeric,
  clicks_during bigint,
  clicks_per_day_before numeric,
  impressions_during bigint
)
language plpgsql
security definer
set search_path = public
stable
as $$
declare
  promo event_promotions%rowtype;
  v_from timestamptz;
  v_to timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' and not can_access_promotion_invoice(p_promotion_id) then
    raise exception 'Keine Berechtigung.';
  end if;
  select * into promo from event_promotions where id = p_promotion_id;
  if not found or promo.starts_at is null then return; end if;
  v_from := promo.starts_at;
  v_to := least(now(), coalesce(promo.ends_at, now()));

  return query select
    greatest(extract(epoch from (v_to - v_from)) / 86400.0, 1.0 / 24)::numeric,
    (select count(*) from event_views v where v.event_id = promo.event_id and v.viewed_at >= v_from and v.viewed_at < v_to),
    (select count(*) / 14.0 from event_views v where v.event_id = promo.event_id and v.viewed_at >= v_from - interval '14 days' and v.viewed_at < v_from)::numeric,
    (select count(*) from ticket_clicks c where c.event_id = promo.event_id and c.clicked_at >= v_from and c.clicked_at < v_to),
    (select count(*) / 14.0 from ticket_clicks c where c.event_id = promo.event_id and c.clicked_at >= v_from - interval '14 days' and c.clicked_at < v_from)::numeric,
    (select count(*) from home_feed_impressions i where i.event_id = promo.event_id and i.shown_at >= v_from and i.shown_at < v_to);
end;
$$;

revoke all on function promotion_performance(uuid) from public, anon;
grant execute on function promotion_performance(uuid) to authenticated, service_role;
